using System.Collections;using System.Collections.Generic;using Alterverse.AI;using Alterverse.Combat;using Alterverse.Visuals;using UnityEngine;using UnityEngine.InputSystem;
namespace Alterverse.Characters
{
[RequireComponent(typeof(CharacterController)),RequireComponent(typeof(Health))]public sealed class VeyrAbilities:MonoBehaviour
{
[SerializeField]private float shadowStrikeCooldown=5f,soulRendCooldown=6f,nullStepCooldown=7f,endFutureCooldown=14f;private const float ArenaHalfWidth=41f,ArenaHalfHeight=35f;private static readonly Color ShadowColor=new(.62f,.14f,.96f),SoulColor=new(.48f,.08f,.78f),FutureColor=new(.86f,.20f,1f);private CharacterController controller;private Health selfHealth;private TeamMember selfTeam;private float qReady,eReady,rReady,fReady;public float QRemaining=>Mathf.Max(0,qReady-Time.time);public float ERemaining=>Mathf.Max(0,eReady-Time.time);public float RRemaining=>Mathf.Max(0,rReady-Time.time);public float FRemaining=>Mathf.Max(0,fReady-Time.time);
private bool CanAct=>selfHealth!=null&&!selfHealth.IsDead;private void Awake(){controller=GetComponent<CharacterController>();selfHealth=GetComponent<Health>();selfTeam=GetComponent<TeamMember>();}private void Update(){if(Keyboard.current==null||!CanAct)return;if(Keyboard.current.qKey.wasPressedThisFrame)ShadowStrike();if(Keyboard.current.eKey.wasPressedThisFrame)SoulRend();if(Keyboard.current.rKey.wasPressedThisFrame)NullStep();if(Keyboard.current.fKey.wasPressedThisFrame)EndOfFuture();}
public bool ShadowStrike(){if(!CanAct||Time.time<qReady)return false;Health t=FindNearestEnemy(5.5f);if(t==null)return false;qReady=Time.time+shadowStrikeCooldown;Vector3 start=transform.position,behind=-t.transform.forward;behind.y=0;if(behind.sqrMagnitude<.01f)behind=(transform.position-t.transform.position).normalized;Vector3 dest=ClampToArena(t.transform.position+behind.normalized*1.25f);PrototypeVfx.ShadowTrail(start,dest,ShadowColor);PrototypeVfx.Ring(start,ShadowColor,1.25f,.18f);Teleport(dest);Face(t.transform.position);PrototypeVfx.Ring(transform.position,ShadowColor,1.45f,.2f);PrototypeVfx.Slash(transform,ShadowColor,2.2f);t.TakeDamage(26f,gameObject);PrototypeVfx.Burst(t.transform.position,ShadowColor,1.05f,9);return true;}
public bool SoulRend(){if(!CanAct||Time.time<eReady)return false;eReady=Time.time+soulRendCooldown;PrototypeVfx.Ring(transform.position,SoulColor,2.8f,.38f);PrototypeVfx.Burst(transform.position,SoulColor,1.25f,10);Collider[] hits=Physics.OverlapSphere(transform.position,2.8f,~0,QueryTriggerInteraction.Ignore);HashSet<Health> damaged=new();float total=0;foreach(Collider hit in hits){Health h=hit.GetComponentInParent<Health>();if(!IsEnemy(h)||!damaged.Add(h))continue;h.TakeDamage(30f,gameObject);PrototypeVfx.SoulLink(h.transform.position,transform.position,SoulColor);PrototypeVfx.Burst(h.transform.position,SoulColor,.9f,7);total+=30;}if(total>0){selfHealth.Heal(total*.3f);PrototypeVfx.Burst(transform.position,new Color(.18f,.85f,.42f),.65f,6);}return true;}
public bool NullStep(){if(!CanAct||Time.time<rReady)return false;rReady=Time.time+nullStepCooldown;Vector3 start=transform.position,dest=ClampToArena(transform.position+transform.forward*4.2f);PrototypeVfx.ShadowTrail(start,dest,ShadowColor);PrototypeVfx.Ring(start,ShadowColor,.9f,.16f);Teleport(dest);PrototypeVfx.Ring(transform.position,ShadowColor,1.5f,.24f);PrototypeVfx.Slash(transform,ShadowColor,1.75f);Health t=FindNearestEnemy(2.2f);if(t!=null){t.TakeDamage(16f,gameObject);PrototypeVfx.Burst(t.transform.position,ShadowColor,.75f,6);}return true;}
public bool EndOfFuture(){if(!CanAct||Time.time<fReady)return false;Health t=FindNearestEnemy(7.5f);if(t==null)return false;fReady=Time.time+endFutureCooldown;PrototypeVfx.FutureMark(t.transform,FutureColor,1.15f);StartCoroutine(ResolveUltimate(t));return true;}private IEnumerator ResolveUltimate(Health t){yield return new WaitForSeconds(1.15f);if(!CanAct||t==null||t.IsDead||!IsEnemy(t))yield break;float damage=30+t.Current*.28f;PrototypeVfx.Ring(t.transform.position,FutureColor,3.1f,.42f);PrototypeVfx.Burst(t.transform.position,FutureColor,1.7f,14);t.TakeDamage(damage,gameObject);}
private Health FindNearestEnemy(float radius){Collider[] hits=Physics.OverlapSphere(transform.position,radius,~0,QueryTriggerInteraction.Ignore);Health closest=null;float closestSqr=float.MaxValue;HashSet<Health> seen=new();foreach(Collider hit in hits){Health h=hit.GetComponentInParent<Health>();if(!seen.Add(h)||!IsEnemy(h))continue;float sqr=(h.transform.position-transform.position).sqrMagnitude;if(sqr<closestSqr){closestSqr=sqr;closest=h;}}return closest;}private bool IsEnemy(Health h){if(h==null||h==selfHealth||h.IsDead)return false;TeamMember m=h.GetComponent<TeamMember>();if(m!=null&&selfTeam!=null)return m.Team!=selfTeam.Team;int team=selfTeam!=null?selfTeam.Team:0;LaneMinion minion=h.GetComponent<LaneMinion>();if(minion!=null)return minion.Team!=team;LaneTower tower=h.GetComponent<LaneTower>();if(tower!=null)return tower.Team!=team;return h.GetComponent<PrototypeEnemyBot>()!=null;}private static Vector3 ClampToArena(Vector3 p)=>GameplayCollision.ClampToRoundedArena(p,ArenaHalfWidth,ArenaHalfHeight);private void Face(Vector3 p){p.y=transform.position.y;transform.LookAt(p);}private void Teleport(Vector3 p){if(controller==null||!controller.enabled)return;controller.enabled=false;transform.position=p;controller.enabled=true;}
}}
